16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.Digits;
22	import jakarta.validation.constraints.NotEmpty;
23	import jakarta.validation.constraints.Pattern;
24	
25	import java.time.LocalDate;
26	import java.util.*;
27	
28	/**
29	 * Simple JavaBean domain object representing an owner.
30	 *
31	 * @author Ken Krebs
32	 * @author Juergen Hoeller
33	 * @author Sam Brannen
34	 * @author Michael Isvy
35	 */
36	@Entity
37	@Table(name = "owners")
38	public class Owner extends Person {
39	    @Column(name = "address")
40	    @NotEmpty
41	    private String address;
42	
43	    @Column(name = "city")
44	    @NotEmpty
45	    private String city;
46	
47	    @Column(name = "telephone")
48	    @NotEmpty
49	    @Digits(fraction = 0, integer = 10)
50	    @Pattern(regexp = "^[0-9]{10}$", message = "Phone number must be exactly 10 digits")
51	    private String telephone;
52	
53	    @Column(name = "email")
54	    private String email;
55	
56	    @Column(name = "registration_date")
57	    private LocalDate registrationDate;
58	
59	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
60	    private Set<Pet> pets;
61	
62	    public String getAddress() {
63	        return this.address;
64	    }
65	
66	    public void setAddress(String address) {
67	        this.address = address;
68	    }
69	
70	    public String getCity() {
71	        return this.city;
72	    }
73	
74	    public void setCity(String city) {
75	        this.city = city;
76	    }
77	
78	    public String getTelephone() {
79	        return this.telephone;
80	    }
81	
82	    public void setTelephone(String telephone) {
83	        this.telephone = telephone;
84	    }
85	
86	    public String getEmail() {
87	        return this.email;
88	    }
89	
90	    public void setEmail(String email) {
91	        this.email = email;
92	    }
93	
94	    public LocalDate getRegistrationDate() {
95	        return this.registrationDate;
96	    }
97	
98	    public void setRegistrationDate(LocalDate registrationDate) {
99	        this.registrationDate = registrationDate;
100	    }
101	
102	    protected Set<Pet> getPetsInternal() {
103	        if (this.pets == null) {
104	            this.pets = new HashSet<>();
105	        }
106	        return this.pets;
107	    }
108	
109	    protected void setPetsInternal(Set<Pet> pets) {
110	        this.pets = pets;
111	    }
112	
113	    public List<Pet> getPets() {
114	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
115	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
116	        return Collections.unmodifiableList(sortedPets);
117	    }
118	
119	    public void setPets(List<Pet> pets) {
120	        this.pets = new HashSet<>(pets);
121	    }
122	
123	    public void addPet(Pet pet) {
124	        getPetsInternal().add(pet);
125	        pet.setOwner(this);
126	    }
127	
128	    /**
129	     * Return the Pet with the given name, or null if none found for this Owner.
130	     *
131	     * @param name to test
132	     * @return true if pet name is already in use
133	     */
134	    public Pet getPet(String name) {
135	        return getPet(name, false);
136	    }
137	
138	    /**
139	     * Return the Pet with the given name, or null if none found for this Owner.
140	     *
141	     * @param name to test
142	     * @return true if pet name is already in use
143	     */
144	    public Pet getPet(String name, boolean ignoreNew) {
145	        name = name.toLowerCase();
146	        for (Pet pet : getPetsInternal()) {
147	            if (!ignoreNew || !pet.isNew()) {
148	                String compName = pet.getName();
149	                compName = compName.toLowerCase();
150	                if (compName.equals(name)) {
151	                    return pet;
152	                }
153	            }
154	        }
155	        return null;
156	    }
157	
158	    public Pet getPet(Integer petId) {
159	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
160	    }
161	
162	    @Override
163	    public String toString() {
164	        return new ToStringCreator(this)
165	
166	            .append("id", this.getId())
167	            .append("new", this.isNew())
168	            .append("lastName", this.getLastName())
169	            .append("firstName", this.getFirstName())
170	            .append("address", this.address)
171	            .append("city", this.city)
172	            .append("telephone", this.telephone)
173	            .append("email", this.email)
174	            .toString();
175	    }
176	}
