217	    /**
218	     * Rejects an owner whose {@code firstName}, {@code lastName}, {@code address}, {@code city}
219	     * or {@code telephone} is missing or blank. A field that is only whitespace is treated as
220	     * blank. When any field fails, a {@link RequiredFieldsMissingException} is thrown carrying
221	     * the names of every offending field, which the exception advice renders as a 400 response
222	     * with an {@code errors} array.
223	     *
224	     * @param ownerFieldsDto the submitted owner fields
225	     */
226	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
227	        List<String> missing = new ArrayList<>();
228	        addIfBlank(missing, "firstName", ownerFieldsDto.getFirstName());
229	        addIfBlank(missing, "lastName", ownerFieldsDto.getLastName());
230	        addIfBlank(missing, "address", ownerFieldsDto.getAddress());
231	        addIfBlank(missing, "city", ownerFieldsDto.getCity());
232	        addIfBlank(missing, "telephone", ownerFieldsDto.getTelephone());
233	        if (!missing.isEmpty()) {
234	            throw new RequiredFieldsMissingException(missing);
235	        }
236	    }
237	
238	    private void addIfBlank(List<String> missing, String fieldName, String value) {
239	        if (value == null || value.isBlank()) {
240	            missing.add(fieldName);
241	        }
242	    }
243	
244	    /**
245	     * Normalizes a submitted telephone number by removing every non-digit character and
246	     * requiring the result to be exactly ten digits. The normalized ten-digit value is
247	     * what gets stored and returned. When the stripped value is not exactly ten digits an
248	     * {@link InvalidFieldsException} is thrown, which the exception advice renders as a
249	     * 400 response naming the {@code telephone} field.
250	     *
251	     * @param telephone the submitted telephone value
252	     * @return the normalized ten-digit telephone
253	     */
254	    private String normalizeTelephone(String telephone) {
255	        String digits = telephone == null ? "" : telephone.replaceAll("\\D", "");
256	        if (digits.length() != 10) {
257	            throw new InvalidFieldsException(List.of("telephone"));
258	        }
259	        return digits;
260	    }
261	
262	    /**
263	     * Pattern for a syntactically valid email address: a non-empty local part, an {@code @},
264	     * and a domain containing at least one dot, none of the parts holding whitespace or a
265	     * second {@code @}.
266	     */
267	    private static final java.util.regex.Pattern EMAIL_PATTERN =
268	        java.util.regex.Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
269	
270	    /**
271	     * Normalizes an optional owner email. An email is optional, so a {@code null} value is
272	     * accepted and returned unchanged. When present it must be a syntactically valid address;
273	     * the value is stored and returned lower-cased. When present but invalid an
274	     * {@link InvalidFieldsException} is thrown, which the exception advice renders as a 400
275	     * response naming the {@code email} field.
276	     *
277	     * @param email the submitted email value, or {@code null} when omitted
278	     * @return the lower-cased email, or {@code null} when none was supplied
279	     */
280	    private String normalizeEmail(String email) {
281	        if (email == null) {
282	            return null;
283	        }
284	        String trimmed = email.trim();
285	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
286	            throw new InvalidFieldsException(List.of("email"));
287	        }
288	        return trimmed.toLowerCase(java.util.Locale.ROOT);
289	    }
290	
291	    /**
292	     * Rejects a new owner whose normalized telephone is already used by any existing owner.
293	     * The telephone is stored in its normalized ten-digit form, so a plain equality check
294	     * against every owner's telephone is sufficient. When a match is found a
295	     * {@link DuplicateTelephoneException} is thrown, which the exception advice renders as a
296	     * 409 Conflict response.
297	     *
298	     * @param telephone the normalized telephone of the owner being created
299	     */
300	    private void rejectDuplicateTelephone(String telephone) {
301	        boolean taken = this.clinicService.findAllOwners().stream()
302	            .anyMatch(existing -> telephone.equals(existing.getTelephone()));
303	        if (taken) {
304	            throw new DuplicateTelephoneException(telephone);
305	        }
306	    }
307	}
